int main() {
    int N;
    cin >> N;

    if (N == 2) {
        cout << -1 << '\n';
        return 0;
    }

    if (N == 1) {
        cout << 1 << '\n';
        return 0;
    }

    int T = N * (N - 1) / 2;
    int scale = T + 1;
    vector<int> values;

    for (int i = 1; i < N; ++i) {
        values.push_back(i);
