    values.push_back(T);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (j) cout << ' ';
            cout << values[i] * scale + values[j];
        }
        cout << '\n';
    }

    return 0;
}
